--Retrieve Detailed Patient Lab History

SELECT
    p.PatientID, p.Name, p.Age, p.gender, d.DiagnosisName , o.OutcomeName, l.TestName,  l.Result, l.NormalRange
FROM Patients AS p
INNER JOIN Diagnosis AS d
    ON p.DiagnosisID = d.DiagnosisID
INNER JOIN Outcome AS o
    ON p.OutcomeID = o.OutcomeID
INNER JOIN Labs AS l
    ON p.PatientID = l.PatientID;

--Average lab results by Diagnosis

SELECT
    d.DiagnosisName, l.TestName, AVG(l.Result) AS AvgResult
FROM Patients AS p
JOIN Diagnosis AS d
    ON p.DiagnosisID = d.DiagnosisID
JOIN Labs AS l
    ON p.PatientID = l.PatientID
GROUP BY
    d.DiagnosisName,
    l.TestName

--count of abnormal lab result
select p.patientID,p.name,COUNT(*)as abnormalcount
from Patients p
join Labs as l
on p.PatientID=l.PatientID
where(l.TestName='Blood Sugar' and l.Result>120)or
(l.TestName='cholestrol' and l.Result>200) or
(l.TestName='Hemoglobin' and l.Result<13)
group by p.PatientID,p.Name
order by abnormalcount desc;


--Diagnoses with highest treatment costs
select d.diagnosisname ,
sum(p.treatmentcost) as Totalcost
from Patients as p
join diagnosis as d 
on p.diagnosisid=d.diagnosisid
group by d.diagnosisname
order by TotalCost desc;

--patient at risk by age and gender
select p.patientid,p.name,d.DiagnosisName,o.outcomename
from Patients as p
join Diagnosis as d
on p.diagnosisid =d.diagnosisid
join Outcome as o
on p.OutcomeID=o.OutcomeID
where p.Age>65 and gender='M' and o.outcomename !='recovered';

--lab trends over time for a specific patient
select l.testname,l.result,p.admissiondate
from labs as l
join Patients as  p 
on l.PatientID=p.PatientID
where p.PatientID in (2,4,6,8,10,12)
order by p.AdmissionDate;

--distribution of outcomes by diagnosis
select d.diagnosisname,o.OutcomeName,count(*) as outcomecount
from Patients as p
join Diagnosis as d
on p.DiagnosisID=d.DiagnosisID
join Outcome as o
on p.OutcomeID=o.OutcomeID
group by d.DiagnosisName,o.OutcomeName
order by d.DiagnosisName,o.OutcomeName desc;






































